        columnas: [{ k: 'n', t: 'Persona' }, { k: 'correo', t: 'Correo' }, { k: 'rolN', t: 'Rol' }, { k: 'unidad', t: 'Unidad' }, { k: 'estado', t: 'Estado', html: (f) => insig(f.estado, f.estado === 'Activa' ? 'ok' : 'aviso') }, { k: 'a', t: 'Acciones', orden: false, noCSV: true, html: (f) => menuAcciones('Acciones de ' + f.n, [{ t: 'Editar', acc: 'per-editar', arg: f.id, ic: 'editar' }, { t: f.estado === 'Activa' ? 'Suspender' : 'Reactivar', acc: 'per-suspender', arg: f.id, ic: 'candado' }, { t: 'Dar de baja', acc: 'per-baja', arg: f.id, ic: 'papelera' }], { id: 'mp-' + f.id, clase: 'boton-icono', soloIcono: true }) }],
        filtros: [{ k: 'rolN', t: 'Rol' }, { k: 'estado', t: 'Estado' }, { k: 'unidad', t: 'Unidad' }],
